\label{ccthm1}
Let $k:=1+|p|+|q|$. If $y$ is any solution to \eqref{cct4} on $I_\ensuremath{\mathbb{T}}$ then
\begin{equation}\label{cct5}
 \|y(t)\|_2 \le \|y(t_0)\|_2e_k(t,t_0), \quad t\in I_\ensuremath{\mathbb{T}}, \quad t\ge t_0.
\end{equation}

\label{thmT}
Let $\ensuremath{\mathbb{T}}$ be a time scale and let $p$, $q$ and $r$ be real--valued right--dense continuous scalar functions of $t\in\ensuremath{\mathbb{T}}$ with $p$ and $q$ satisfying the regressivity condition
\begin{equation}\label{regT}
 1+\mu(t)\left[-p(t)+\mu(t)q(t)\right]\neq 0, \quad t\in\ensuremath{\mathbb{T}}^\kappa.
\end{equation}
For all $t \in \ensuremath{\mathbb{T}}$, let $y_1$ and $y_2$ satisfy
\begin{equation}\label{homoslomo}
 y_i^{\Delta\Delta}(t)+p(t)y_i^\Delta(t)+q(t)y_i(t)=0, \quad i=1,2, 
\end{equation}
and $W(t):=y_1(t)y_2^\Delta(t)-y_2(t)y_1^\Delta(t)\neq 0$.
The general solution of the linear inhomogeneous second--order ordinary dynamic equation
$$ y^{\Delta\Delta}(t)+p(t)y^{\Delta}(t)+q(t)y(t)=r(t), \quad t\in\ensuremath{\mathbb{T}}^{\kappa^2}, $$
is
\begin{equation}\label{odynform1}
 y(t)=c_1y_1(t)+c_2y_2(t)+y_1(t)\int \frac{e_{(-p+\mu q)}(t,a)\int r(t)y_1^\sigma(t)e_{\ominus(-p+\mu q)}(\sigma(t),a) \Delta t} {y_1(t)y_1^\sigma(t)}\Delta t
\end{equation}
or
\begin{equation}\label{odynform2}
 y(t)=c_1y_1(t)+c_2y_2(t)+y_2(t)\int \frac{e_{(-p+\mu q)}(t,a)\int r(t)y_2^\sigma(t)e_{\ominus(-p+\mu q)}(\sigma(t),a) \Delta t} {y_2(t)y_2^\sigma(t)}\Delta t,
\end{equation}
where $c_1$ and $c_2$ are arbitrary constants and $e_{(-p+\mu q)}(\cdot,a)$ is the time--scale exponential function.

\label{roo}
Assume $p$ and $q$ are real--valued right--dense continuous scalar functions of $t\in\ensuremath{\mathbb{T}}$ satisfying the regressivity condition
\begin{equation}\label{regTpos}
 1+\mu(t)\left[-p(t)+\mu(t)q(t)\right]\neq 0, \quad t\in\ensuremath{\mathbb{T}}^{\kappa}.
\end{equation}
If $y_1$ is a solution of the linear homogeneous second--order ordinary dynamic equation \eqref{homot}, then
\begin{equation}\label{rooy2}
 y_2(t)=y_1(t)\int \frac{e_{(-p+\mu q)}(t,a)}{y_1(t)y_1^\sigma(t)}\Delta t
\end{equation}
is a second linearly independent solution of \eqref{homot}. Similarly, if $y_2$ is a solution of \eqref{homot}, then
\begin{equation}\label{rooy1}
 y_1(t)=y_2(t)\int \frac{e_{(-p+\mu q)}(t,a)}{y_2(t)y_2^\sigma(t)}\Delta t
\end{equation}
is a second linearly independent solution of \eqref{homot}.

It is also possible to show the equivalence of the result shown in \eqref{ydform} with that due to the variation of parameters formula in equation \eqref{bpvp}. Let $y_1$ be a solution of the linear homogeneous equation \eqref{homot}. Assuming \eqref{regTpos}, and appropriating the Wronskian of $y_1$ and the form of $y_2$ given in \eqref{rooy2} as calculated in \eqref{Wron12}, the solution given in \eqref{bpvp} is
\begin{eqnarray}
 y_d(t) &=& y_2(t)\int_{a}^{t}\frac{y_1^\sigma(s)r(s)}{e_{(-p+\mu q)}(\sigma(s),a)}\Delta s - y_1(t)\int_{a}^{t}\frac{y_2^\sigma(s)r(s)}{e_{(-p+\mu q)}(\sigma(s),a)}\Delta s \nonumber  \\
 &=& \left(y_1(t)\int_{a}^{t} \frac{e_{(-p+\mu q)}(s,a)}{y_1(s)y_1^\sigma(s)}\Delta s\right)\int_{a}^{t} r(s)y_1^\sigma(s)e_{\ominus(-p+\mu q)}(\sigma(s),a)\Delta s \nonumber \\
 & & -y_1(t)\int_{a}^{t}r(s)y_1^\sigma(s)e_{\ominus(-p+\mu q)}(\sigma(s),a)\int_{a}^{\sigma(s)}
 \frac{e_{(-p+\mu q)}(\xi,a)}{y_1(\xi)y_1^\sigma(\xi)}\Delta \xi\Delta s.\label{ydequivvp}
\end{eqnarray}
If we use the integration by parts formula $\int fg^\Delta\Delta t=f(t)g(t)-\int f^\Delta g^\sigma\Delta t$, see \cite[Theorem 1.77(vi)]{bp1}, on the integral in \eqref{ydform}, where we have taken
$$ f(t)=\int_{a}^{t}r(s)y_1^\sigma(s)e_{\ominus(-p+\mu q)}(\sigma(s),a)\Delta s \quad\text{and}\quad g^\Delta(t)=\frac{e_{(-p+\mu q)}(t,a)}{y_1(t)y_1^\sigma(t)}, $$ 
we get \eqref{ydequivvp}.

\label{corT}
Let $\alpha$, $\beta$ and $r$ be real--valued right--dense continuous scalar functions on $\ensuremath{\mathbb{T}}$ with $\alpha$ satisfying the regressivity condition $1+\mu(t)\alpha(t)\neq 0$ for $t\in\ensuremath{\mathbb{T}}^{\kappa}$. For all $t \in \ensuremath{\mathbb{T}}$, let
 $y_1$ and $y_2$ satisfy 
\begin{equation}\label{corhomoslomo}
 y_i^{\Delta\Delta}(t)+\alpha(t)y_i^{\Delta\sigma}(t)+\beta(t)y_i^\sigma(t)=0, \quad i=1,2, 
\end{equation}
with $W(t):=y_1(t)y_2^\Delta(t)-y_2(t)y_1^\Delta(t)\neq 0$. The general solution of the linear inhomogeneous second--order ordinary dynamic equation
\begin{equation}\label{bp3.6}
 y^{\Delta\Delta}(t)+\alpha(t)y^{\Delta\sigma}(t)+\beta(t)y^\sigma(t)=r(t), \quad t\in\ensuremath{\mathbb{T}}^{\kappa^2}, 
\end{equation}
is
\begin{equation}\label{corodynform1}
 y(t)=c_1y_1(t)+c_2y_2(t)+y_1(t)\int\frac{e_{\ominus\alpha}(t,a)\int r(t)y_1^\sigma(t)e_{\alpha}(\sigma(t),a) \Delta t}{y_1(t)y_1^\sigma(t)}\Delta t
\end{equation}
or
\begin{equation}\label{corodynform2}
 y(t)=c_1y_1(t)+c_2y_2(t)+y_2(t)\int\frac{e_{\ominus\alpha}(t,a)\int r(t)y_2^\sigma(t)e_{\alpha}(\sigma(t),a) \Delta t}{y_2(t)y_2^\sigma(t)}\Delta t,
\end{equation}
where $c_1$ and $c_2$ are arbitrary constants, and where $e_{\alpha}(\cdot,a)$ is the time-scale exponential function.

\label{resultz}
Let $p$, $q$ and $r$ be real--valued scalar functions of $t\in\ensuremath{\mathbb{Z}}$ with $p$ and $q$ satisfying the regressivity condition
\begin{equation}
 1-p(t)+q(t)\neq 0,  \quad t\in\ensuremath{\mathbb{Z}}.
\end{equation}
Let $y_1$ and $y_2$ satisfy 
$$ \Delta^2y_i(t)+p(t)\Delta  y_i(t)+q(t)y_i(t)=0, \quad i=1,2, $$
and $W(t):=y_1(t)\Delta  y_2(t)-y_2(t)\Delta  y_1(t)\neq 0$.
The general solution of the linear inhomogeneous second--order ordinary difference equation
$$ \Delta^2y(t) + p(t)\Delta y(t) + q(t)y(t) = r(t), \quad t\in\ensuremath{\mathbb{Z}}, $$
is given by
\begin{equation}\label{odiffform1} 
 y(t) = c_1 y_1(t) + c_2 y_2(t) + y_1(t) \sum \frac{\prod_{j=a}^{t-1} \left(1-p(j)+q(j)\right) \sum \frac{r(t)y_1(t+1)} {\prod_{j=a}^{t}\left(1-p(j)+q(j)\right)}} {y_1(t)y_1(t+1)}
\end{equation}
or
\begin{equation}\label{odiffform2}
y(t)=c_1y_1(t)+c_2y_2(t)+y_2(t)\sum\frac{\prod_{j=a}^{t-1}\left(1-p(j)+q(j)\right)\sum\frac{r(t)y_2(t+1)}{\prod_{j=a}^{t}\left(1-p(j)+q(j)\right)}}{y_2(t)y_2(t+1)},
\end{equation}
and where $c_1$ and $c_2$ are arbitrary constants.

\label{resultz2}
Let $\alpha$, $\beta$ and $r$ be real--valued scalar functions of $t\in\ensuremath{\mathbb{Z}}$ with regressivity condition $\beta(t)\neq 0$ for $t\in\ensuremath{\mathbb{Z}}$.
Let $y_1$ and $y_2$ satisfy 
$$ y_i(t+2)+\alpha(t)y_i(t+1)+\beta(t)y_i(t)=0, \quad i=1,2, $$
with $W(t):=y_1(t)y_2(t+1)-y_2(t)y_1(t+1)\neq 0$.
The general solution of the linear inhomogeneous second--order ordinary difference equation
\begin{equation}\label{elaydiform}
 y(t+2) + \alpha(t)y(t+1) + \beta(t)y(t) = r(t), \quad t\in\ensuremath{\mathbb{Z}}, 
\end{equation}
is given by
\begin{equation}\label{odiffform12} 
 y(t) = c_1 y_1(t) + c_2 y_2(t) + y_1(t) \sum \frac{\prod_{j=a}^{t-1} \beta(j) \sum \frac{r(t)y_1(t+1)} {\prod_{j=a}^{t}\beta(j)}} {y_1(t)y_1(t+1)}
\end{equation}
or
\begin{equation}\label{odiffform22}
y(t)=c_1y_1(t)+c_2y_2(t)+y_2(t)\sum\frac{\prod_{j=a}^{t-1}\beta(j)\sum\frac{r(t)y_2(t+1)}{\prod_{j=a}^{t}\beta(j)}}{y_2(t)y_2(t+1)},
\end{equation}
where $c_1$ and $c_2$ are arbitrary constants.
